  --font-serif: "Lora", Georgia, serif;
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-success: var(--success);
  --color-warning: var(--warning);
  --color-danger: var(--danger);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
}

:root {
  --radius: 0rem;
  --background: oklch(1 0 0);
  --foreground: oklch(0.13 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.13 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.13 0 0);
  --primary: oklch(0.13 0 0);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.13 0 0);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.48 0 0);
  --accent: oklch(0.96 0 0);
  --accent-foreground: oklch(0.13 0 0);
  --destructive: oklch(0.42 0.14 27);
  --destructive-foreground: oklch(1 0 0);
  --success: oklch(0.4 0.07 152);
  --warning: oklch(0.5 0.09 62);
  --danger: oklch(0.42 0.14 27);
  --border: oklch(0.9 0 0);
  --input: oklch(0.9 0 0);
  --ring: oklch(0.13 0 0);
  --sidebar: oklch(1 0 0);
  --sidebar-foreground: oklch(0.13 0 0);
  --sidebar-accent: oklch(0.96 0 0);
  --sidebar-accent-foreground: oklch(0.13 0 0);
  --sidebar-border: oklch(0.9 0 0);
}

@layer base {
  * {
    border-color: var(--color-border);
  }

  body {
    background-color: var(--color-background);
    color: var(--color-foreground);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
  }

  h1,
  h2,
  h3,
  h4 {
    font-family: var(--font-sans);
    font-weight: 800;
    letter-spacing: -0.045em;
    line-height: 1.05;
  }

  p {
    font-family: var(--font-serif);
    letter-spacing: 0;
    line-height: 1.65;
  }

  [class*="rounded"] {
    border-radius: 0 !important;
  }

  [class*="shadow"] {
    box-shadow: none !important;
  }

  .text-xs {
    letter-spacing: 0.08em;
    text-transform: uppercase;
    font-family: var(--font-sans);
    font-weight: 600;
  }

  a[class*="bg-primary"],
  button[class*="bg-primary"] {
    text-transform: uppercase;
    letter-spacing: 0.12em;
    font-size: 0.75rem;
    font-weight: 700;
  }
}

