import { createFileRoute } from "@tanstack/react-router";
import { useQueryClient } from "@tanstack/react-query";
import { AlertTriangle, CheckCircle2, ChevronDown, Clock, HelpCircle, Scale } from "lucide-react";
import { useState } from "react";

import { useCaseViews } from "../data/caseViews";
import type { Tone } from "../data/lottoDemoCases";
import {
  getMonitoringRun,
  monitoringCasesQueryKey,
  reviewMonitoringCase,
  startMonitoringRun,
} from "../lib/monitoring-api";

export const Route = createFileRoute("/hinweise")({
  head: () => ({
    meta: [
      { title: "Hinweise – Muc Legal Monitoring" },
      {
        name: "description",
        content:
          "Aktuelle Hinweise aus dem Monitoring als Benachrichtigungen – mit Zeitstempel, Kontext und vollständiger Beweisführung.",
      },
      { property: "og:title", content: "Hinweise – Muc Legal Monitoring" },
      {
        property: "og:description",
        content:
          "Aktuelle Hinweise aus dem Monitoring als Benachrichtigungen – mit Zeitstempel, Kontext und vollständiger Beweisführung.",
      },
      { property: "og:type", content: "website" },
      { name: "twitter:card", content: "summary" },
    ],
  }),
  component: HinweisePage,
});

const toneIcon: Record<Tone, typeof Scale> = {
  danger: AlertTriangle,
  success: CheckCircle2,
  warning: HelpCircle,
  neutral: Clock,
};

const toneColor: Record<Tone, string> = {
  danger: "text-danger bg-danger/10",
  success: "text-success bg-success/10",
  warning: "text-warning bg-warning/10",
  neutral: "text-muted-foreground bg-muted",
};

const toneLabel: Record<Tone, string> = {
  danger: "Kritisch",
  success: "In Ordnung",
  warning: "Prüfung nötig",
  neutral: "Ausstehend",
};

function relativeTime(iso: string | null) {
  if (!iso) return "geplant";
  const now = Date.now();
  const mins = Math.max(1, Math.round((now - new Date(iso).getTime()) / 60000));
  if (mins < 60) return `vor ${mins} Min.`;
  const hours = Math.round(mins / 60);
  if (hours < 24) return `vor ${hours} Std.`;
  return `vor ${Math.round(hours / 24)} Tg.`;
}

function formatDateTime(iso: string | null) {
  if (!iso) return "—";
  return new Date(iso).toLocaleString("de-DE", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    timeZone: "Europe/Berlin",
  });
}

function HinweisePage() {
  const { cases } = useCaseViews();
  const queryClient = useQueryClient();
  const [openId, setOpenId] = useState<string | null>(null);
  const [actionState, setActionState] = useState<Record<string, string>>({});

  async function decide(caseId: string, decision: "freigegeben" | "abgelehnt") {
    setActionState((state) => ({ ...state, [caseId]: "Entscheidung wird gespeichert …" }));
    try {
      await reviewMonitoringCase(caseId, decision);
      await queryClient.invalidateQueries({ queryKey: monitoringCasesQueryKey });
      setActionState((state) => ({
        ...state,
        [caseId]: decision === "freigegeben" ? "Fall wurde freigegeben." : "Fall wurde abgelehnt.",
      }));
    } catch (error) {
      setActionState((state) => ({
        ...state,
        [caseId]: error instanceof Error ? error.message : "Entscheidung fehlgeschlagen.",
      }));
    }
  }

  async function startRun(caseId: string) {
    setActionState((state) => ({ ...state, [caseId]: "Monitoringlauf wird gestartet …" }));
    try {
      let run = await startMonitoringRun(caseId);
      setActionState((state) => ({ ...state, [caseId]: run.message }));
      const terminal = new Set([
        "referenzzustand_dokumentiert",
        "unveraendert_fortbestehend",
        "beseitigt",
        "kerngleich_wiederaufgetreten",
        "neuer_sachverhalt",
        "unsicher",
        "pruefung_unvollstaendig",
        "failed",
      ]);
      for (let attempt = 0; attempt < 240 && !terminal.has(run.status); attempt += 1) {
        await new Promise((resolve) => window.setTimeout(resolve, 500));
        run = await getMonitoringRun(run.run_id);
        setActionState((state) => ({ ...state, [caseId]: run.message }));
      }
    } catch (error) {
      setActionState((state) => ({
        ...state,
        [caseId]: error instanceof Error ? error.message : "Monitoringlauf fehlgeschlagen.",
      }));
    }
  }

  return (
    <div className="min-h-screen bg-background px-6 py-10 sm:px-10">
      <div className="mx-auto max-w-3xl">
        <ul className="space-y-4">
          {cases.map((c) => {
            const Icon = toneIcon[c.tone];
            const isOpen = openId === c.case_id;
            return (
              <li key={c.case_id}>
                <article
                  className={`group rounded-2xl border border-border bg-card p-5 shadow-sm transition-all hover:shadow-md ${
                    isOpen ? "ring-1 ring-ring" : ""
                  }`}
                >
                  <button
                    type="button"
                    onClick={() => setOpenId(isOpen ? null : c.case_id)}
                    className="w-full text-left"
                    aria-expanded={isOpen}
                  >
                    <div className="flex items-start gap-4">
                      <span
                        className={`mt-0.5 grid size-10 shrink-0 place-items-center rounded-full ${toneColor[c.tone]}`}
                      >
                        <Icon className="size-5" strokeWidth={1.75} />
                      </span>
                      <div className="min-w-0 flex-1">
                        <div className="flex items-start justify-between gap-3">
                          <div>
                            <p className="text-xs font-medium text-muted-foreground">
                              {toneLabel[c.tone]} · {relativeTime(c.found_at)}
                            </p>
                            <p className="mt-0.5 text-base font-semibold text-card-foreground">
                              {c.title}
                            </p>
                          </div>
                          <ChevronDown
                            className={`size-5 shrink-0 text-muted-foreground transition-transform duration-200 ${
                              isOpen ? "rotate-180" : ""
                            }`}
                          />
                        </div>
                        <p className="mt-1 text-sm text-card-foreground">{c.status}</p>
                        <p className="mt-1 line-clamp-2 text-sm text-muted-foreground">
                          {c.explanation}
                        </p>
                        <p className="mt-3 text-xs text-muted-foreground">
                          {formatDateTime(c.found_at)}
                        </p>
                      </div>
                    </div>
                  </button>

                  {isOpen && (
                    <div className="mt-5 border-t border-border pt-4">
                      <div className="rounded-xl border border-primary/20 bg-primary/5 p-5">
                        <p className="text-xs font-medium tracking-wider text-primary uppercase">
                          Tenor / Formulierungsvorschlag
                        </p>
                        <p className="mt-2 font-serif text-base leading-relaxed text-foreground">
                          {c.tenor.formulierung}
                        </p>
                        <p className="mt-3 text-xs leading-relaxed text-muted-foreground">
                          {c.tenor.hinweis}
                        </p>
                      </div>

                      <div className="mt-4 grid gap-4 sm:grid-cols-2">
                        <div className="rounded-xl bg-muted p-4">
                          <p className="text-xs font-medium tracking-wider text-muted-foreground uppercase">
                            Kontext
                          </p>
                          <p className="mt-1 text-sm text-foreground">{c.secondary}</p>
                        </div>
                        <div className="rounded-xl bg-muted p-4">
                          <p className="text-xs font-medium tracking-wider text-muted-foreground uppercase">
                            Details
                          </p>
                          <ul className="mt-1 space-y-1 text-sm text-foreground">
                            <li>
                              <span className="text-muted-foreground">Fall-ID:</span> {c.fall_id}
                            </li>
                            <li>
                              <span className="text-muted-foreground">Domain:</span> {c.domain}
                            </li>
                            {c.confidence !== null && (
                              <li>
                                <span className="text-muted-foreground">Confidence:</span>{" "}
                                {Math.round(c.confidence * 100)} %
                              </li>
                            )}
                          </ul>
                        </div>
                      </div>

                      <div className="mt-4 rounded-xl border border-border bg-background p-5">
                        <p className="font-serif text-lg tracking-tight text-foreground">
                          Beweisführung
                        </p>

                        <dl className="mt-4 grid gap-4 sm:grid-cols-2">
                          <div>
                            <dt className="text-xs font-medium tracking-wider text-muted-foreground uppercase">
                              Fundstelle
                            </dt>
                            <dd className="mt-1 text-sm text-foreground">
                              {c.evidence.fundstelle}
                            </dd>
                          </div>
                          <div>
                            <dt className="text-xs font-medium tracking-wider text-muted-foreground uppercase">
                              Erfassung
                            </dt>
                            <dd className="mt-1 text-sm text-foreground">{c.evidence.erfassung}</dd>
                          </div>
                        </dl>

                        <p className="mt-5 text-xs font-medium tracking-wider text-muted-foreground uppercase">
                          Beweiskette
                        </p>
                        <ol className="mt-2 space-y-2">
                          {c.evidence.kette.map((step, i) => (
                            <li key={step} className="flex gap-3 text-sm text-foreground">
                              <span className="grid size-5 shrink-0 place-items-center rounded-full bg-primary/10 text-[11px] font-semibold text-primary">
                                {i + 1}
                              </span>
                              <span className="leading-relaxed">{step}</span>
                            </li>
                          ))}
                        </ol>

                        <div className="mt-5 grid gap-4 sm:grid-cols-2">
                          <div>
                            <p className="text-xs font-medium tracking-wider text-muted-foreground uppercase">
                              Rechtliche Einordnung
                            </p>
                            <p className="mt-1 text-sm leading-relaxed text-foreground">
                              {c.evidence.einordnung}
                            </p>
                          </div>
                          <div>
                            <p className="text-xs font-medium tracking-wider text-muted-foreground uppercase">
                              Offene Punkte
                            </p>
                            <p className="mt-1 text-sm leading-relaxed text-foreground">
                              {c.evidence.offen}
                            </p>
                          </div>
                        </div>
                      </div>

                      <div className="mt-4 flex items-center gap-3">
                        <a
                          href={c.url}
                          target="_blank"
                          rel="noreferrer"
                          className="inline-flex items-center rounded-full bg-primary px-4 py-2 text-sm font-medium text-primary-foreground transition-opacity hover:opacity-90"
                        >
                          Zielseite öffnen
                        </a>
                        <span className="truncate text-xs text-muted-foreground">{c.url}</span>
                      </div>

                      {c.source === "backend" && (
                        <div className="mt-4 border-t border-border pt-4">
                          <p className="text-xs text-muted-foreground">Menschliche Entscheidung</p>
                          <div className="mt-3 flex flex-wrap gap-3">
                            {c.decision === "weitere_pruefung" && (
                              <>
                                <button
                                  type="button"
                                  onClick={(event) => {
                                    event.stopPropagation();
                                    void decide(c.case_id, "freigegeben");
                                  }}
                                  className="bg-primary px-4 py-2 text-sm text-primary-foreground"
                                >
                                  Fall freigeben
                                </button>
                                <button
                                  type="button"
                                  onClick={(event) => {
                                    event.stopPropagation();
                                    void decide(c.case_id, "abgelehnt");
                                  }}
                                  className="border border-border px-4 py-2 text-sm text-foreground"
                                >
                                  Ablehnen
                                </button>
                              </>
                            )}
                            {c.decision === "freigegeben" && (
                              <button
                                type="button"
                                onClick={(event) => {
                                  event.stopPropagation();
                                  void startRun(c.case_id);
                                }}
                                className="bg-primary px-4 py-2 text-sm text-primary-foreground"
                              >
                                Monitoring starten
                              </button>
                            )}
                          </div>
                          {actionState[c.case_id] && (
                            <p className="mt-3 text-sm text-muted-foreground" role="status">
                              {actionState[c.case_id]}
                            </p>
                          )}
                        </div>
                      )}
                    </div>
                  )}
                </article>
              </li>
            );
          })}
        </ul>
      </div>
    </div>
  );
}

import { createFileRoute } from "@tanstack/react-router";
import { useQuery } from "@tanstack/react-query";
import { X } from "lucide-react";
import { useState } from "react";

import { useCaseViews, type CaseView } from "../data/caseViews";
import type { Tone } from "../data/lottoDemoCases";
import {
  listTenorArchiveEntries,
  type TenorArchiveRecord,
  type TenorDecision,
} from "../lib/tenor-api";

export const Route = createFileRoute("/archiv")({
  head: () => ({
    meta: [
      { title: "Archiv – Muc Legal Monitoring" },
      {
        name: "description",
        content: "Übersicht aller erfassten Fälle und gespeicherten Tenore.",
      },
      { property: "og:title", content: "Archiv – Muc Legal Monitoring" },
      {
        property: "og:description",
        content: "Übersicht aller erfassten Fälle und gespeicherten Tenore.",
      },
      { property: "og:type", content: "website" },
      { name: "twitter:card", content: "summary" },
    ],
  }),
  component: ArchivPage,
});

const toneBadge: Record<Tone, string> = {
  danger: "bg-danger/10 text-danger",
  success: "bg-success/10 text-success",
  warning: "bg-warning/10 text-warning",
  neutral: "bg-muted text-muted-foreground",
};

const toneLabel: Record<Tone, string> = {
  danger: "Kritisch",
  success: "In Ordnung",
  warning: "Prüfung nötig",
  neutral: "Ausstehend",
};

function formatDateTime(iso: string | null) {
  if (!iso) return "—";
  return new Date(iso).toLocaleString("de-DE", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    timeZone: "Europe/Berlin",
  });
}

function ArchivPage() {
  const { cases } = useCaseViews();
  const tenorQuery = useQuery({
    queryKey: ["tenor-archive"],
    queryFn: listTenorArchiveEntries,
  });
  const tenors = tenorQuery.data?.tenors ?? [];
  const [section, setSection] = useState<"faelle" | "tenore">("faelle");
  const [selected, setSelected] = useState<CaseView | null>(null);
  const [selectedTenor, setSelectedTenor] = useState<TenorArchiveRecord | null>(null);

  return (
    <div className="mx-auto max-w-6xl px-8 py-12">
      <h1 className="text-3xl">Archiv</h1>
      <p className="mt-3 max-w-xl text-sm text-muted-foreground">
        {section === "faelle"
          ? `Alle erfassten Fälle in der Übersicht. ${cases.length} Einträge.`
          : `Alle bisher gespeicherten Tenore. ${tenors.length} Einträge.`}
      </p>

      <div
        role="tablist"
        aria-label="Archivbereich"
        className="mt-8 inline-flex border border-foreground"
      >
        <ArchiveTab
          label={`Fälle (${cases.length})`}
          selected={section === "faelle"}
          onClick={() => setSection("faelle")}
        />
        <ArchiveTab
          label={`Tenore (${tenors.length})`}
          selected={section === "tenore"}
          onClick={() => setSection("tenore")}
          divided
        />
      </div>

      {section === "faelle" ? (
        <div className="mt-5 overflow-hidden rounded-2xl border border-border bg-card">
          <div className="overflow-x-auto">
            <table className="w-full min-w-[820px] text-left text-sm">
              <thead>
                <tr className="border-b border-border text-xs tracking-wider text-muted-foreground uppercase">
                  <th className="px-5 py-4 font-medium">Fall-ID</th>
                  <th className="px-5 py-4 font-medium">Titel</th>
                  <th className="px-5 py-4 font-medium">Status</th>
                  <th className="px-5 py-4 font-medium">Domain</th>
                  <th className="px-5 py-4 font-medium">Erfasst</th>
                  <th className="px-5 py-4 font-medium">Confidence</th>
                </tr>
              </thead>
              <tbody>
                {cases.map((item) => (
                  <tr
                    key={item.case_id}
                    onClick={() => setSelected(item)}
                    tabIndex={0}
                    onKeyDown={(event) => {
                      if (event.key === "Enter" || event.key === " ") {
                        event.preventDefault();
                        setSelected(item);
                      }
                    }}
                    className="cursor-pointer border-b border-border last:border-0 transition-colors hover:bg-muted/60"
                  >
                    <td className="px-5 py-4 font-mono text-xs text-muted-foreground">
                      {item.fall_id}
                    </td>
                    <td className="px-5 py-4">
                      <p className="font-medium text-card-foreground">{item.title}</p>
                      <p className="mt-0.5 text-xs text-muted-foreground">{item.secondary}</p>
                    </td>
                    <td className="px-5 py-4">
                      <span
                        className={`inline-flex rounded-full px-3 py-1 text-xs font-medium ${toneBadge[item.tone]}`}
                      >
                        {toneLabel[item.tone]}
                      </span>
                      <p className="mt-1 text-xs text-muted-foreground">{item.status}</p>
                    </td>
                    <td className="px-5 py-4 text-muted-foreground">{item.domain}</td>
                    <td className="px-5 py-4 text-muted-foreground">
                      {formatDateTime(item.found_at)}
                    </td>
                    <td className="px-5 py-4 text-muted-foreground">
                      {item.confidence === null ? "—" : `${Math.round(item.confidence * 100)} %`}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      ) : (
        <TenorArchiveTable
          tenors={tenors}
          loading={tenorQuery.isLoading}
          error={tenorQuery.isError}
          onSelect={setSelectedTenor}
        />
      )}

      {selected && <CaseDetail item={selected} onClose={() => setSelected(null)} />}
      {selectedTenor && <TenorDetail item={selectedTenor} onClose={() => setSelectedTenor(null)} />}
    </div>
  );
}

function ArchiveTab({
  label,
  selected,
  onClick,
  divided = false,
}: {
  label: string;
  selected: boolean;
  onClick: () => void;
  divided?: boolean;
}) {
  return (
    <button
      type="button"
      role="tab"
      aria-selected={selected}
      onClick={onClick}
      className={`min-h-10 px-5 text-xs font-medium transition-colors ${divided ? "border-l border-foreground" : ""} ${selected ? "bg-foreground text-background" : "bg-background text-muted-foreground hover:bg-muted"}`}
    >
      {label}
    </button>
  );
}

const decisionLabel: Record<TenorDecision, string> = {
  freigegeben: "Freigegeben",
  abgelehnt: "Abgelehnt",
  weitere_pruefung: "Weitere Prüfung",
};

function tenorStatus(item: TenorArchiveRecord) {
  if (item.decision) return decisionLabel[item.decision];
  return item.source === "minimal" ? "Übernommen" : "Prüfung offen";
}

function strategyLabel(item: TenorArchiveRecord) {
  if (item.strategy === "precise") return "Präzise";
  if (item.strategy === "neutral") return "Technikneutral";
  return item.strategy.replaceAll("_", " ");
}

function TenorArchiveTable({
  tenors,
  loading,
  error,
  onSelect,
}: {
  tenors: TenorArchiveRecord[];
  loading: boolean;
  error: boolean;
  onSelect: (item: TenorArchiveRecord) => void;
}) {
  if (loading) {
    return <p className="mt-8 text-sm text-muted-foreground">Tenorarchiv wird geladen …</p>;
