                  </div>
                )}

                {questionLoading && (
                  <p className="flex items-center gap-2 text-sm text-slate-300" aria-live="polite">
                    <Loader2 className="size-3.5 animate-spin" /> KI liest deine Ergänzung …
                  </p>
