    setErrors({});
    setSubmitError(null);
    setRecord(null);
    setSubmitting(true);
    try {
      setRecord(await createTenorDraft(payload));
    } catch (error) {
      setSubmitError(
        error instanceof Error ? error.message : "Der Entwurf konnte nicht erzeugt werden.",
      );
    } finally {
      setSubmitting(false);
    }
  }

