          ))}
        </ul>
      ) : (
        <p className="text-sm text-muted-foreground">Keine Angabe im Entwurf.</p>
      )}
    </section>
  );
}

function Field({
  label,
  error,
  full = false,
  children,
}: {
  label: string;
  error: string | undefined;
  full?: boolean;
  children: React.ReactNode;
}) {
  return (
    <label className={full ? "sm:col-span-2" : undefined}>
