import { createFileRoute } from "@tanstack/react-router";
import { LayoutTemplate, PenLine } from "lucide-react";
import { useState } from "react";

import { MaskTenorView } from "../components/tenor/MaskTenorView";
import { MinimalTenorView } from "../components/tenor/MinimalTenorView";

export const Route = createFileRoute("/tenorhilfe")({
  head: () => ({
    meta: [
      { title: "Tenorschreibhilfe – Muc Legal Monitoring" },
      {
        name: "description",
        content:
          "Unterlassungstenor wahlweise in einer strukturierten Maske oder einem minimalen Schreibmodus entwerfen.",
      },
      { property: "og:title", content: "Tenorschreibhilfe – Muc Legal Monitoring" },
      {
        property: "og:description",
        content:
          "Unterlassungstenor wahlweise in einer strukturierten Maske oder einem minimalen Schreibmodus entwerfen.",
      },
      { property: "og:type", content: "website" },
      { name: "twitter:card", content: "summary" },
    ],
  }),
  component: TenorhilfePage,
});

type ViewMode = "minimal" | "maske";

function TenorhilfePage() {
  const [view, setView] = useState<ViewMode>("minimal");

  return (
    <div className="min-h-screen bg-background">
      <header className="sticky top-0 z-30 flex h-16 items-center justify-between border-b border-border bg-background/95 px-6 backdrop-blur sm:px-10">
        <div>
          <span className="text-xs text-muted-foreground">Tenorschreibhilfe</span>
          <p className="mt-0.5 font-sans text-sm font-semibold">
            {view === "minimal"
              ? "Lokale, referenzierte Bausteinvorschläge"
              : "Backend-Entwurf & menschliche Freigabe"}
          </p>
        </div>
        <div
          role="tablist"
          aria-label="Ansicht der Tenorschreibhilfe"
          className="flex border border-foreground"
        >
          <button
            id="tenor-tab-minimal"
            type="button"
            role="tab"
            aria-selected={view === "minimal"}
            aria-controls="tenor-panel-minimal"
            onClick={() => setView("minimal")}
            className={`flex min-h-10 items-center gap-2 px-4 text-xs transition-colors ${
              view === "minimal"
                ? "bg-foreground text-background"
                : "bg-background text-muted-foreground hover:bg-muted"
            }`}
          >
            <PenLine className="size-3.5" />
            Minimal
          </button>
          <button
            id="tenor-tab-maske"
            type="button"
            role="tab"
            aria-selected={view === "maske"}
            aria-controls="tenor-panel-maske"
            onClick={() => setView("maske")}
            className={`flex min-h-10 items-center gap-2 border-l border-foreground px-4 text-xs transition-colors ${
              view === "maske"
                ? "bg-foreground text-background"
                : "bg-background text-muted-foreground hover:bg-muted"
            }`}
          >
            <LayoutTemplate className="size-3.5" />
            Maske
          </button>
        </div>
      </header>

      <section
        id="tenor-panel-minimal"
        role="tabpanel"
        aria-labelledby="tenor-tab-minimal"
        hidden={view !== "minimal"}
      >
        <MinimalTenorView />
      </section>
      <section
        id="tenor-panel-maske"
        role="tabpanel"
        aria-labelledby="tenor-tab-maske"
        hidden={view !== "maske"}
      >
        <MaskTenorView />
      </section>
    </div>
  );
}
import { createFileRoute } from "@tanstack/react-router";
import { useQuery } from "@tanstack/react-query";
import { X } from "lucide-react";
import { useState } from "react";

import { useCaseViews, type CaseView } from "../data/caseViews";
import type { Tone } from "../data/lottoDemoCases";
import {
  listTenorArchiveEntries,
  type TenorArchiveRecord,
  type TenorDecision,
} from "../lib/tenor-api";

export const Route = createFileRoute("/archiv")({
  head: () => ({
    meta: [
      { title: "Archiv – Muc Legal Monitoring" },
      {
        name: "description",
        content: "Übersicht aller erfassten Fälle und gespeicherten Tenore.",
      },
      { property: "og:title", content: "Archiv – Muc Legal Monitoring" },
      {
        property: "og:description",
        content: "Übersicht aller erfassten Fälle und gespeicherten Tenore.",
      },
      { property: "og:type", content: "website" },
      { name: "twitter:card", content: "summary" },
    ],
  }),
  component: ArchivPage,
});

const toneBadge: Record<Tone, string> = {
  danger: "bg-danger/10 text-danger",
  success: "bg-success/10 text-success",
  warning: "bg-warning/10 text-warning",
  neutral: "bg-muted text-muted-foreground",
};

const toneLabel: Record<Tone, string> = {
  danger: "Kritisch",
  success: "In Ordnung",
  warning: "Prüfung nötig",
  neutral: "Ausstehend",
};

function formatDateTime(iso: string | null) {
  if (!iso) return "—";
  return new Date(iso).toLocaleString("de-DE", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    timeZone: "Europe/Berlin",
  });
}

function ArchivPage() {
  const { cases } = useCaseViews();
  const tenorQuery = useQuery({
    queryKey: ["tenor-archive"],
    queryFn: listTenorArchiveEntries,
  });
  const tenors = tenorQuery.data?.tenors ?? [];
  const [section, setSection] = useState<"faelle" | "tenore">("faelle");
  const [selected, setSelected] = useState<CaseView | null>(null);
  const [selectedTenor, setSelectedTenor] = useState<TenorArchiveRecord | null>(null);

  return (
    <div className="mx-auto max-w-6xl px-8 py-12">
      <h1 className="text-3xl">Archiv</h1>
      <p className="mt-3 max-w-xl text-sm text-muted-foreground">
        {section === "faelle"
          ? `Alle erfassten Fälle in der Übersicht. ${cases.length} Einträge.`
          : `Alle bisher gespeicherten Tenore. ${tenors.length} Einträge.`}
      </p>

      <div
        role="tablist"
        aria-label="Archivbereich"
        className="mt-8 inline-flex border border-foreground"
      >
        <ArchiveTab
          label={`Fälle (${cases.length})`}
          selected={section === "faelle"}
          onClick={() => setSection("faelle")}
        />
        <ArchiveTab
          label={`Tenore (${tenors.length})`}
          selected={section === "tenore"}
          onClick={() => setSection("tenore")}
          divided
        />
      </div>

      {section === "faelle" ? (
        <div className="mt-5 overflow-hidden rounded-2xl border border-border bg-card">
          <div className="overflow-x-auto">
            <table className="w-full min-w-[820px] text-left text-sm">
              <thead>
                <tr className="border-b border-border text-xs tracking-wider text-muted-foreground uppercase">
                  <th className="px-5 py-4 font-medium">Fall-ID</th>
                  <th className="px-5 py-4 font-medium">Titel</th>
                  <th className="px-5 py-4 font-medium">Status</th>
                  <th className="px-5 py-4 font-medium">Domain</th>
                  <th className="px-5 py-4 font-medium">Erfasst</th>
                  <th className="px-5 py-4 font-medium">Confidence</th>
                </tr>
              </thead>
              <tbody>
                {cases.map((item) => (
                  <tr
                    key={item.case_id}
                    onClick={() => setSelected(item)}
                    tabIndex={0}
                    onKeyDown={(event) => {
                      if (event.key === "Enter" || event.key === " ") {
                        event.preventDefault();
                        setSelected(item);
                      }
                    }}
                    className="cursor-pointer border-b border-border last:border-0 transition-colors hover:bg-muted/60"
                  >
                    <td className="px-5 py-4 font-mono text-xs text-muted-foreground">
                      {item.fall_id}
                    </td>
                    <td className="px-5 py-4">
                      <p className="font-medium text-card-foreground">{item.title}</p>
                      <p className="mt-0.5 text-xs text-muted-foreground">{item.secondary}</p>
                    </td>
                    <td className="px-5 py-4">
                      <span
                        className={`inline-flex rounded-full px-3 py-1 text-xs font-medium ${toneBadge[item.tone]}`}
                      >
                        {toneLabel[item.tone]}
                      </span>
                      <p className="mt-1 text-xs text-muted-foreground">{item.status}</p>
                    </td>
                    <td className="px-5 py-4 text-muted-foreground">{item.domain}</td>
                    <td className="px-5 py-4 text-muted-foreground">
                      {formatDateTime(item.found_at)}
                    </td>
                    <td className="px-5 py-4 text-muted-foreground">
                      {item.confidence === null ? "—" : `${Math.round(item.confidence * 100)} %`}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      ) : (
        <TenorArchiveTable
          tenors={tenors}
          loading={tenorQuery.isLoading}
          error={tenorQuery.isError}
          onSelect={setSelectedTenor}
        />
      )}

      {selected && <CaseDetail item={selected} onClose={() => setSelected(null)} />}
      {selectedTenor && <TenorDetail item={selectedTenor} onClose={() => setSelectedTenor(null)} />}
    </div>
  );
}

function ArchiveTab({
  label,
  selected,
  onClick,
  divided = false,
}: {
  label: string;
  selected: boolean;
  onClick: () => void;
  divided?: boolean;
}) {
  return (
    <button
      type="button"
      role="tab"
      aria-selected={selected}
      onClick={onClick}
      className={`min-h-10 px-5 text-xs font-medium transition-colors ${divided ? "border-l border-foreground" : ""} ${selected ? "bg-foreground text-background" : "bg-background text-muted-foreground hover:bg-muted"}`}
    >
      {label}
    </button>
  );
}

const decisionLabel: Record<TenorDecision, string> = {
  freigegeben: "Freigegeben",
  abgelehnt: "Abgelehnt",
  weitere_pruefung: "Weitere Prüfung",
};

function tenorStatus(item: TenorArchiveRecord) {
  if (item.decision) return decisionLabel[item.decision];
  return item.source === "minimal" ? "Übernommen" : "Prüfung offen";
}

function strategyLabel(item: TenorArchiveRecord) {
  if (item.strategy === "precise") return "Präzise";
  if (item.strategy === "neutral") return "Technikneutral";
  return item.strategy.replaceAll("_", " ");
}

function TenorArchiveTable({
  tenors,
  loading,
  error,
  onSelect,
}: {
  tenors: TenorArchiveRecord[];
  loading: boolean;
  error: boolean;
  onSelect: (item: TenorArchiveRecord) => void;
}) {
  if (loading) {
    return <p className="mt-8 text-sm text-muted-foreground">Tenorarchiv wird geladen …</p>;
  }
  if (error) {
    return (
      <p role="alert" className="mt-8 text-sm text-danger">
        Das Tenorarchiv konnte nicht geladen werden.
      </p>
    );
  }
  if (!tenors.length) {
    return (
      <div className="mt-5 rounded-2xl border border-border bg-card px-6 py-12 text-center">
        <p className="font-serif text-lg text-foreground">Noch keine Tenore gespeichert.</p>
        <p className="mt-2 text-sm text-muted-foreground">
          Ein Entwurf erscheint hier, sobald er in der Tenorschreibhilfe übernommen wurde.
        </p>
      </div>
    );
  }
  return (
    <div className="mt-5 overflow-hidden rounded-2xl border border-border bg-card">
      <div className="overflow-x-auto">
        <table className="w-full min-w-[760px] text-left text-sm">
          <thead>
            <tr className="border-b border-border text-xs tracking-wider text-muted-foreground uppercase">
              <th className="px-5 py-4 font-medium">Fall-ID</th>
              <th className="px-5 py-4 font-medium">Tenor</th>
              <th className="px-5 py-4 font-medium">Variante</th>
              <th className="px-5 py-4 font-medium">Status</th>
              <th className="px-5 py-4 font-medium">Gespeichert</th>
            </tr>
          </thead>
          <tbody>
            {tenors.map((item) => (
              <tr
                key={item.tenor_id}
                tabIndex={0}
                onClick={() => onSelect(item)}
                onKeyDown={(event) => {
                  if (event.key === "Enter" || event.key === " ") {
                    event.preventDefault();
                    onSelect(item);
                  }
                }}
                className="cursor-pointer border-b border-border last:border-0 transition-colors hover:bg-muted/60"
              >
                <td className="px-5 py-4 font-mono text-xs text-muted-foreground">
                  {item.fall_id}
                </td>
                <td className="max-w-md px-5 py-4">
                  <p className="font-medium text-card-foreground">{item.title}</p>
                  <p className="mt-1 line-clamp-2 font-serif text-xs leading-5 text-muted-foreground">
                    {item.text}
                  </p>
                </td>
                <td className="px-5 py-4 text-muted-foreground">{strategyLabel(item)}</td>
                <td className="px-5 py-4">
                  <span className="inline-flex rounded-full bg-muted px-3 py-1 text-xs font-medium text-foreground">
                    {tenorStatus(item)}
                  </span>
                </td>
                <td className="px-5 py-4 text-muted-foreground">
                  {formatDateTime(item.created_at)}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function TenorDetail({ item, onClose }: { item: TenorArchiveRecord; onClose: () => void }) {
  return (
    <div
      className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-foreground/30 p-4 backdrop-blur-sm sm:p-8"
      onClick={onClose}
      role="presentation"
    >
      <article
        className="w-full max-w-4xl rounded-3xl border border-border bg-card p-6 shadow-xl sm:p-10"
        onClick={(event) => event.stopPropagation()}
        role="dialog"
        aria-modal="true"
        aria-label={item.title}
      >
        <div className="flex items-start justify-between gap-4">
          <div>
            <p className="font-mono text-xs text-muted-foreground">{item.fall_id}</p>
            <h2 className="mt-1 text-2xl tracking-tight text-card-foreground">{item.title}</h2>
            <p className="mt-2 text-xs text-muted-foreground">
              {strategyLabel(item)} · {tenorStatus(item)} · {formatDateTime(item.created_at)}
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            aria-label="Schließen"
            className="grid size-10 shrink-0 place-items-center rounded-full text-muted-foreground transition-colors hover:bg-muted"
          >
            <X className="size-5" />
          </button>
        </div>

        <div className="mt-8 border-y border-border py-8">
          <p className="text-xs font-medium tracking-wider text-muted-foreground uppercase">
            Gespeicherter Tenor
          </p>
          <p className="mt-4 whitespace-pre-wrap font-serif text-lg leading-9 text-foreground">
            {item.text}
          </p>
        </div>

        <dl className="mt-7 grid gap-5 text-sm sm:grid-cols-2">
          <Detail label="Schuldner" value={item.schuldner} />
          <Detail
            label="Erstellung"
            value={`${item.source === "minimal" ? "Minimal" : "Maske"} · ${item.model}`}
          />
          <Detail label="Wissensstand" value={item.reference_version} />
          <Detail
            label="Quellenanker"
            value={item.source_ids.length ? item.source_ids.join(" · ") : "—"}
          />
        </dl>

        <div className="mt-7 rounded-2xl bg-muted p-5">
          <p className="text-xs tracking-wider text-muted-foreground uppercase">Sachverhalt</p>
          <p className="mt-2 whitespace-pre-wrap text-sm leading-7 text-foreground">
            {item.context}
          </p>
        </div>
      </article>
    </div>
  );
}

