                "source_ids": [],
                "decision": record["decision"],
                "decided_at": record["decided_at"],
            }
            for record in tenor_drafts.list()
        ]
        entries = sorted(
            [*minimal_entries, *mask_entries],
            key=lambda item: item["created_at"],
            reverse=True,
        )
        return {"tenors": entries}

